const complex = document.getElementById('complex-para');
const second = document.getElementById('second-para');
const short = document.getElementById('short-para');
const footer = document.getElementById('footer-para');
const buttons = document.querySelectorAll('.ai4a11y-plain-btn');

if (!complex || !second || !short) return false;

if (!buttons.length) {
  return !complex.nextElementSibling?.classList.contains('ai4a11y-plain-btn');
}

const btn1 = complex.nextElementSibling;
const btn2 = second.nextElementSibling;
if (!btn1?.classList.contains('ai4a11y-plain-btn')) return false;
if (!btn2?.classList.contains('ai4a11y-plain-btn')) return false;

if (short.nextElementSibling?.classList.contains('ai4a11y-plain-btn')) return false;
if (footer?.nextElementSibling?.classList.contains('ai4a11y-plain-btn')) return false;

for (const btn of [btn1, btn2]) {
  if (btn.tagName !== 'BUTTON') return false;
  if (btn.type !== 'button') return false;
  if (btn.textContent.trim() !== 'Plain language') return false;
  const rect = btn.getBoundingClientRect();
  if (rect.width < 24 || rect.height < 24) return false;
  btn.focus();
  if (document.activeElement !== btn) return false;
  btn.blur();
}
return true;

const complex = document.getElementById('complex-para');
if (!complex) return false;
const btn = complex.nextElementSibling;
if (!btn || !btn.classList.contains('ai4a11y-plain-btn')) return true;

await window.__verifyClick('#complex-para + .ai4a11y-plain-btn');
await new Promise((r) => setTimeout(r, 60));

const replaced = document.querySelector('[data-ai4a11y-replaced]');
if (!replaced) return false;
if (!complex.hasAttribute('hidden')) return false;
if (btn.textContent.trim() !== 'Show original') return false;
if (!replaced.textContent.includes('Welfare Department announced you can appeal')) return false;

await window.__verifyClick('#complex-para ~ .ai4a11y-plain-btn');
await new Promise((r) => setTimeout(r, 60));
if (complex.hasAttribute('hidden')) return false;
if (!replaced.hasAttribute('hidden')) return false;
if (btn.textContent.trim() !== 'Show simplified') return false;

await window.__verifyClick('#complex-para ~ .ai4a11y-plain-btn');
await new Promise((r) => setTimeout(r, 60));
if (!complex.hasAttribute('hidden')) return false;
if (replaced.hasAttribute('hidden')) return false;
if (btn.textContent.trim() !== 'Show original') return false;

await window.__verifyClick('#complex-para ~ .ai4a11y-plain-btn');
await new Promise((r) => setTimeout(r, 60));
return true;

